const res = pm.response.json();
if (res.accessToken) {
  pm.environment.set("accessToken", res.accessToken);
}
if (res.refreshToken) {
  pm.environment.set("refreshToken", res.refreshToken);
}

pm.test("Logout successful", function () {
  pm.response.to.have.status(200);
});

// Clear values of all environment variables except baseUrl
const allVars = pm.environment.toObject();
Object.keys(allVars).forEach(function(key) {
  if (key !== "baseUrl") {
    pm.environment.set(key, "");
  }
});

console.log("All environment variable values cleared except baseUrl.");

pm.test("Status is 201", function () {
  pm.response.to.have.status(201);
});

const jsonData = pm.response.json();

if (jsonData.series && jsonData.series._id) {
  pm.collectionVariables.set("seriesId", jsonData.series._id);
}

pm.test("Create release issue returns 201", function () {
  pm.response.to.have.status(201);
});

const jsonData = pm.response.json();
if (jsonData.data && jsonData.data.id) {
  pm.collectionVariables.set("issueId", jsonData.data.id);
}

// Kiểm tra API trả về mã thành công 200 hoặc 201
pm.test("Status code is 200 or 201", function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 201]);
});

// Tự động lấy ID của trang vừa tạo lưu vào biến môi trường
var res = pm.response.json();
var id = res._id || res.id || (res.data && (res.data._id || res.data.id));
if (id) {
    pm.environment.set("page_id", id);
    console.log("Đã lưu page_id:", id);
}

